<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Generative AI Competitive Landscape: User Sentiment & Complaint Analysis Q1 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --chatgpt:   #10a37f;
    --copilot:   #0078d4;
    --gemini:    #ea4335;
    --perplexity:#6b2fa0;
    --claude:    #d97706;
    --bg:        #f8fafc;
    --surface:   #ffffff;
    --border:    #e2e8f0;
    --text:      #1e293b;
    --muted:     #64748b;
    --accent:    #0f172a;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; }

  /* ── Layout ── */
  .page-header { background: var(--accent); color: #fff; padding: 48px 64px 40px; }
  .page-header .kicker { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: #94a3b8; margin-bottom: 12px; }
  .page-header h1 { font-size: 28px; font-weight: 700; line-height: 1.3; max-width: 780px; }
  .page-header .meta { margin-top: 16px; font-size: 13px; color: #94a3b8; display: flex; gap: 24px; flex-wrap: wrap; }
  .page-header .meta span { display: flex; align-items: center; gap: 6px; }

  main { max-width: 1200px; margin: 0 auto; padding: 40px 32px 80px; }

  /* ── Sections ── */
  .section { margin-bottom: 56px; }
  .section-header { display: flex; align-items: baseline; gap: 12px; margin-bottom: 24px; padding-bottom: 12px; border-bottom: 2px solid var(--border); }
  .section-num { font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--muted); min-width: 32px; }
  .section-header h2 { font-size: 20px; font-weight: 700; color: var(--accent); }

  /* ── Executive callouts ── */
  .exec-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; margin-bottom: 28px; }
  .exec-card { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 24px; position: relative; overflow: hidden; }
  .exec-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px; }
  .exec-card.c1::before { background: var(--copilot); }
  .exec-card.c2::before { background: #dc2626; }
  .exec-card.c3::before { background: #7c3aed; }
  .exec-card .num { font-size: 32px; font-weight: 800; color: var(--accent); }
  .exec-card .label { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; color: var(--muted); margin-top: 4px; }
  .exec-card p { font-size: 13px; color: var(--text); margin-top: 10px; line-height: 1.5; }

  /* ── KPI strip ── */
  .kpi-strip { display: grid; grid-template-columns: repeat(5,1fr); gap: 14px; margin-bottom: 32px; }
  .kpi-box { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 16px; text-align: center; }
  .kpi-box .app-dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; margin-bottom: 8px; }
  .kpi-box .kpi-val { font-size: 26px; font-weight: 800; }
  .kpi-box .kpi-label { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.8px; margin-top: 2px; }
  .kpi-box .kpi-sub { font-size: 12px; color: var(--muted); margin-top: 6px; }

  /* ── Charts ── */
  .chart-row { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 28px; }
  .chart-row.three { grid-template-columns: 1fr 1fr 1fr; }
  .chart-card { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 24px; }
  .chart-card.wide { grid-column: 1 / -1; }
  .chart-title { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px; color: var(--muted); margin-bottom: 16px; }
  .chart-wrap { position: relative; }

  /* ── Table ── */
  .data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
  .data-table th { background: #f1f5f9; font-weight: 700; padding: 10px 14px; text-align: left; border-bottom: 2px solid var(--border); font-size: 11px; text-transform: uppercase; letter-spacing: 0.8px; color: var(--muted); }
  .data-table td { padding: 10px 14px; border-bottom: 1px solid var(--border); vertical-align: middle; }
  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: #f8fafc; }
  .app-pill { display: inline-flex; align-items: center; gap: 8px; font-weight: 600; font-size: 13px; }
  .dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }

  /* ── Complaint bars ── */
  .complaint-matrix { overflow-x: auto; }
  .bar-cell { display: flex; align-items: center; gap: 8px; }
  .bar-bg { flex: 1; height: 8px; background: #f1f5f9; border-radius: 4px; min-width: 80px; }
  .bar-fill { height: 100%; border-radius: 4px; }
  .bar-pct { font-size: 12px; font-weight: 600; color: var(--text); min-width: 38px; text-align: right; }

  /* ── Mismatch section ── */
  .mismatch-grid { display: grid; grid-template-columns: repeat(5,1fr); gap: 14px; }
  .mismatch-card { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 18px; text-align: center; }
  .mismatch-card .total-pct { font-size: 24px; font-weight: 800; }
  .mismatch-card .app-name { font-size: 12px; font-weight: 700; margin-top: 6px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.8px; }
  .mismatch-card .breakdown { margin-top: 12px; display: flex; flex-direction: column; gap: 6px; font-size: 11px; }
  .mismatch-card .breakdown span { display: flex; justify-content: space-between; padding: 4px 6px; border-radius: 4px; }
  .mismatch-card .breakdown .hi { background: #fef3c7; color: #92400e; }
  .mismatch-card .breakdown .lo { background: #fee2e2; color: #991b1b; }

  /* ── Recommendations ── */
  .rec-list { display: flex; flex-direction: column; gap: 16px; }
  .rec-item { display: flex; gap: 20px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 20px 24px; }
  .rec-num { font-size: 28px; font-weight: 900; color: var(--border); flex-shrink: 0; width: 40px; line-height: 1; }
  .rec-body h3 { font-size: 15px; font-weight: 700; color: var(--accent); }
  .rec-body p { font-size: 13px; color: var(--muted); margin-top: 6px; line-height: 1.6; }
  .rec-tag { display: inline-block; background: #dbeafe; color: #1e40af; font-size: 10px; font-weight: 700; padding: 2px 8px; border-radius: 100px; text-transform: uppercase; letter-spacing: 0.8px; margin-right: 6px; margin-top: 8px; }
  .rec-tag.red { background: #fee2e2; color: #991b1b; }
  .rec-tag.yellow { background: #fef3c7; color: #92400e; }
  .rec-tag.green { background: #dcfce7; color: #166534; }
  .rec-tag.purple { background: #ede9fe; color: #5b21b6; }

  /* ── Insight boxes ── */
  .insight { background: #f0f9ff; border-left: 4px solid #0ea5e9; padding: 14px 18px; border-radius: 0 8px 8px 0; margin: 16px 0; font-size: 13px; color: #0c4a6e; }
  .insight strong { display: block; margin-bottom: 4px; }

  /* ── Data quality note ── */
  .dq-note { background: #fffbeb; border: 1px solid #fde68a; border-radius: 8px; padding: 14px 18px; font-size: 12px; color: #78350f; margin-top: 16px; }
  .dq-note strong { color: #92400e; }

  /* ── Responsive ── */
  @media (max-width: 900px) {
    .exec-grid, .kpi-strip, .chart-row, .mismatch-grid { grid-template-columns: 1fr 1fr; }
    .page-header { padding: 32px 24px; }
    main { padding: 24px 16px; }
  }
  @media (max-width: 600px) {
    .exec-grid, .kpi-strip, .chart-row, .mismatch-grid { grid-template-columns: 1fr; }
  }

  .legend-row { display: flex; flex-wrap: wrap; gap: 16px; margin-bottom: 20px; }
  .legend-item { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; }

  .stars { color: #f59e0b; }
  .badge { display: inline-block; padding: 2px 10px; border-radius: 100px; font-size: 11px; font-weight: 700; }
  .badge.green { background: #dcfce7; color: #166534; }
  .badge.red { background: #fee2e2; color: #991b1b; }
  .badge.yellow { background: #fef3c7; color: #92400e; }

  footer { text-align: center; padding: 32px; font-size: 12px; color: var(--muted); border-top: 1px solid var(--border); }
</style>
</head>
